import java.util.*;

class Teacher
{
    String name, address, phone, qualification, subject;
    double salary;   // monthly salary
    double tax;      // annual income tax

    void accept()
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter name: ");
        name = sc.nextLine();
        System.out.print("Enter address: ");
        address = sc.nextLine();
        System.out.print("Enter phone number: ");
        phone = sc.nextLine();
        System.out.print("Enter highest qualification: ");
        qualification = sc.nextLine();
        System.out.print("Enter subject specialization: ");
        subject = sc.nextLine();
        System.out.print("Enter monthly salary: ");
        salary = sc.nextDouble();
    }

    void display()
    {
        System.out.println("Name           : " + name);
        System.out.println("Address        : " + address);
        System.out.println("Phone number   : " + phone);
        System.out.println("Qualification  : " + qualification);
        System.out.println("Specialization : " + subject);
        System.out.println("Monthly salary : " + salary);
        System.out.println("Income tax     : " + tax);
    }

    void increment()
    {
        salary = salary + 5000;
    }

    void computeTax()
    {
        double annual = salary * 12;
        if (annual > 150000)
            tax = 0.05 * (annual - 150000);
        else
            tax = 0;
    }

    public static void main(String args[])
    {
        Teacher t = new Teacher();
        t.accept();
        t.increment();
        t.computeTax();
        t.display();
    }
}

// Variable description
// name, address, phone, qualification, subject : String  - teacher's details
// salary : double - monthly salary
// tax    : double - annual income tax
// annual : double - annual salary (local to computeTax)
// t      : Teacher - object used in main

(Corrected: the source program had a misplaced closing brace in accept(), read salary with nextInt() and charged negative tax when the annual salary was below 150000.)

