import java.util.*;

class Box
{
    double length, breadth, height;

    void accept()
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter length, breadth and height: ");
        length = sc.nextDouble();
        breadth = sc.nextDouble();
        height = sc.nextDouble();
    }

    void volume()
    {
        double vol = length * breadth * height;
        System.out.println("Volume of the box = " + vol);
    }

    void area()
    {
        double a = 2 * (length * breadth + breadth * height + height * length);
        System.out.println("Total surface area of the box = " + a);
    }

    public static void main(String args[])
    {
        Box ob = new Box();
        ob.accept();
        ob.volume();
        ob.area();
    }
}

// Variable description
// length, breadth, height : double - dimensions of the box
// vol : double - volume (local)
// a   : double - total surface area (local)
// ob  : Box - object used in main

import java.util.*;

class Friend
{
    int sno, day, month, year;
    String name, address, phone;

    void accept()
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter serial number: ");
        sno = sc.nextInt();
        sc.nextLine();                      // clear the rest of the line
        System.out.print("Enter name: ");
        name = sc.nextLine();
        System.out.print("Enter address: ");
        address = sc.nextLine();
        System.out.print("Enter phone number: ");
        phone = sc.nextLine();
        System.out.print("Enter birth day, month and year: ");
        day = sc.nextInt();
        month = sc.nextInt();
        year = sc.nextInt();
    }

    void display()
    {
        System.out.println("Serial number : " + sno);
        System.out.println("Name          : " + name);
        System.out.println("Address       : " + address);
        System.out.println("Phone number  : " + phone);
        System.out.println("Date of birth : " + day + "/" + month + "/" + year);
