    {
        Friend f1 = new Friend();
        Friend f2 = new Friend();
        f1.accept();
        f2.accept();
        f1.display();
        f2.display();
    }
}

// Variable description
// sno : int - serial number
// name, address, phone : String - friend's details
// day, month, year : int - date of birth
// f1, f2 : Friend - objects used in main

