import java.util.*;

class Table
{
    double length, breadth, height;   // in metres

    void accept()
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter length, breadth and height in metres: ");
        length = sc.nextDouble();
        breadth = sc.nextDouble();
        height = sc.nextDouble();
    }

    void display()
    {
        System.out.println("Length  = " + length + " m");
        System.out.println("Breadth = " + breadth + " m");
        System.out.println("Height  = " + height + " m");
    }

    void convert()
    {
        double cl = length * 100;
        double cb = breadth * 100;
        double ch = height * 100;
        System.out.println("Length in cm  = " + cl);
        System.out.println("Breadth in cm = " + cb);
        System.out.println("Height in cm  = " + ch);
    }

    public static void main(String args[])
    {
        Table ob = new Table();
        ob.accept();
        ob.display();
        ob.convert();
    }
}

// Variable description
// length, breadth, height : double - dimensions in metres
// cl, cb, ch : double - dimensions in centimetres (local to convert)
// ob : Table - object used in main

