import java.util.*;

class ReserveTicket
{
    String name;
    double amount;
    static int count = 0;    // tickets sold, shared by all objects

    void accept()
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter name of the buyer: ");
        name = sc.nextLine();
        System.out.print("Enter amount of the ticket: ");
        amount = sc.nextDouble();
        count++;
    }

    void display()
    {
        System.out.println("Buyer        : " + name);
        System.out.println("Amount       : " + amount);
        System.out.println("Tickets sold : " + count);
    }

    void increase()
    {
        amount = amount + 10;
    }

    public static void main(String args[])
    {
        ReserveTicket t = new ReserveTicket();
        t.accept();
        t.display();
        t.increase();
        System.out.println("After increasing the amount by 10:");
        t.display();
    }
}

// Variable description
// name   : String - buyer's name
// amount : double - ticket amount
// count  : static int - number of tickets sold
// t      : ReserveTicket - object used in main

