Sample check: 5:40:50 and 2:30:20 -> interval 3:10:30, sum 8:11:10.

import java.util.*;

class Time
{
    int hrs, min, sec;

    void accept()
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter hours, minutes and seconds: ");
        hrs = sc.nextInt();
        min = sc.nextInt();
        sec = sc.nextInt();
    }

    void display()
    {
        System.out.println(hrs + " hrs " + min + " min " + sec + " sec");
    }

    int toSeconds()
    {
        return hrs * 3600 + min * 60 + sec;
    }

    void interval(Time t1, Time t2)
    {
        int d = Math.abs(t1.toSeconds() - t2.toSeconds());
        int h = d / 3600;
        int m = (d % 3600) / 60;
        int s = d % 60;
        System.out.println("Interval = " + h + " hrs " + m + " min " + s + " sec");
    }

    void sum(Time t1, Time t2)
    {
        int total = t1.toSeconds() + t2.toSeconds();
        int h = total / 3600;
        int m = (total % 3600) / 60;
        int s = total % 60;
        System.out.println("Sum = " + h + " hrs " + m + " min " + s + " sec");
    }

    public static void main(String args[])
    {
        Time t1 = new Time();
        Time t2 = new Time();
        Time ob = new Time();
        t1.accept();
        t2.accept();
        t1.display();
        t2.display();
        ob.interval(t1, t2);
        ob.sum(t1, t2);
    }
}

// Variable description
// hrs, min, sec : int - time stored in an object
// d     : int - difference in seconds
// total : int - sum in seconds
// h, m, s : int - hours, minutes, seconds of the result
// t1, t2, ob : Time - objects used in main

